{"command":"# Check GitHub advisories for starlette
curl -s "https://api.github.com/advisories?ecosystem=pip&affects=starlette&per_page=20" 2>&1 | python3 -c "
import json, sys
try:
    data = json.load(sys.stdin)
    if isinstance(data, list):
        for adv in data:
            summary = adv.get('summary', '')
            severity = adv.get('severity', '')
            cve = adv.get('cve_id', '')
            ghsa = adv.get('ghsa_id', '')
            published = adv.get('published_at', '')
            vulns = adv.get('vulnerabilities', [])
            affected = []
            for v in vulns:
                pkg = v.get('package', {})
                if pkg.get('name') == 'starlette':
                    affected.append(v.get('vulnerable_version_range', ''))
            if affected:
                print(f'{cve} | {ghsa} | {severity} | {summary}')
                print(f'  Affected ranges: {affected}')
                print(f'  Published: {published}')
                print()
    else:
        print('Response:', data)
except Exception as e:
    print(f'Error: {e}')
    print(sys.stdin.read() if hasattr(sys.stdin, 'read') else '')
" 2>&1"}
